import{_ as t,c as i,o as a,ae as n}from"./chunks/framework.Bw0Gm4PQ.js";const p=JSON.parse('{"title":"H.R.1 - One Big Beautiful Bill Act","description":"","frontmatter":{"legisId":"2025-05-20-big-beautiful-bill","title":"H.R.1 - One Big Beautiful Bill Act","sourceUrl":"https://www.congress.gov/bill/119th-congress/house-bill/1","publishDate":"2025-05-20T00:00:00-05:00","head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"H.R.1 - One Big Beautiful Bill Act\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-05-20-big-beautiful-bill\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"H.R.1 - One Big Beautiful Bill Act\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-05-20-big-beautiful-bill\\",\\"datePublished\\":\\"2025-05-20T00:00:00-05:00\\",\\"dateModified\\":1765502111000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-05-20-big-beautiful-bill\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-05-20-big-beautiful-bill.md","filePath":"congress-bills/2025-05-20-big-beautiful-bill.md","lastUpdated":1765502111000}'),r={name:"congress-bills/2025-05-20-big-beautiful-bill.md"};function l(o,e,s,u,d,m){return a(),i("div",null,e[0]||(e[0]=[n('<h1 id="one-big-beautiful-bill-act" tabindex="-1">One Big Beautiful Bill Act <a class="header-anchor" href="#one-big-beautiful-bill-act" aria-label="Permalink to &quot;One Big Beautiful Bill Act&quot;">​</a></h1><h2 id="title-i-committee-on-agriculture" tabindex="-1">Title I: Committee on Agriculture <a class="header-anchor" href="#title-i-committee-on-agriculture" aria-label="Permalink to &quot;Title I: Committee on Agriculture&quot;">​</a></h2><h3 id="subtitle-a-nutrition" tabindex="-1">Subtitle A: Nutrition <a class="header-anchor" href="#subtitle-a-nutrition" aria-label="Permalink to &quot;Subtitle A: Nutrition&quot;">​</a></h3><p>Reforms eligibility and benefit rules for SNAP recipients, focusing on work requirements and cost control.</p><p><strong><strong>Key takeaways:</strong></strong></p><ul><li>Imposes stricter work requirements for able-bodied adults without dependents.</li><li>Limits waivers and standard utility deductions.</li><li>Reduces internet-related SNAP reimbursements.</li></ul><h3 id="subtitle-b-investment-in-rural-america" tabindex="-1">Subtitle B: Investment in Rural America <a class="header-anchor" href="#subtitle-b-investment-in-rural-america" aria-label="Permalink to &quot;Subtitle B: Investment in Rural America&quot;">​</a></h3><p>Invests in rural economies, agricultural research, and energy development.</p><p><strong>Key takeaways:</strong></p><ul><li>Funds rural safety nets and forestry programs.</li><li>Enhances agricultural trade promotion and conservation efforts.</li><li>Supports energy infrastructure in rural areas.</li></ul><h2 id="title-ii-committee-on-armed-services" tabindex="-1">Title II: Committee on Armed Services <a class="header-anchor" href="#title-ii-committee-on-armed-services" aria-label="Permalink to &quot;Title II: Committee on Armed Services&quot;">​</a></h2><p>Appropriates funds for modernization and readiness of the U.S. military and improves service member quality of life.</p><p><strong>Key takeaways:</strong></p><ul><li>Improves military housing, pay, and health benefits.</li><li>Increases resources for shipbuilding, cybersecurity, and Indo-Pacific defense.</li><li>Expands missile defense and low-cost weapon production.</li></ul><h2 id="title-iii-committee-on-education-and-workforce" tabindex="-1">Title III: Committee on Education and Workforce <a class="header-anchor" href="#title-iii-committee-on-education-and-workforce" aria-label="Permalink to &quot;Title III: Committee on Education and Workforce&quot;">​</a></h2><h3 id="subtitle-a-student-eligibility" tabindex="-1">Subtitle A: Student Eligibility <a class="header-anchor" href="#subtitle-a-student-eligibility" aria-label="Permalink to &quot;Subtitle A: Student Eligibility&quot;">​</a></h3><p>Adjusts definitions of student financial need and cost of attendance.</p><p><strong>Key takeaways:</strong></p><ul><li>Revises how student need is calculated.</li><li>Updates median college cost definitions.</li></ul><h3 id="subtitle-b-loan-limits" tabindex="-1">Subtitle B: Loan Limits <a class="header-anchor" href="#subtitle-b-loan-limits" aria-label="Permalink to &quot;Subtitle B: Loan Limits&quot;">​</a></h3><p>Establishes federal loan caps for different student types.</p><p><strong>Key takeaways:</strong></p><ul><li>Limits borrowing for graduate students and parents.</li><li>Aims to control rising student debt.</li></ul><h3 id="subtitle-c-loan-repayment" tabindex="-1">Subtitle C: Loan Repayment <a class="header-anchor" href="#subtitle-c-loan-repayment" aria-label="Permalink to &quot;Subtitle C: Loan Repayment&quot;">​</a></h3><p>Modifies repayment and forgiveness rules for federal student loans.</p><p><strong>Key takeaways:</strong></p><ul><li>Streamlines loan deferment and forbearance.</li><li>Reforms Public Service Loan Forgiveness terms.</li></ul><h3 id="subtitle-d-pell-grants" tabindex="-1">Subtitle D: Pell Grants <a class="header-anchor" href="#subtitle-d-pell-grants" aria-label="Permalink to &quot;Subtitle D: Pell Grants&quot;">​</a></h3><p>Expands eligibility and program coverage.</p><p><strong>Key takeaways:</strong></p><ul><li>Adds Pell access for short-term workforce programs.</li><li>Addresses funding shortfalls.</li></ul><h3 id="subtitle-e-accountability" tabindex="-1">Subtitle E: Accountability <a class="header-anchor" href="#subtitle-e-accountability" aria-label="Permalink to &quot;Subtitle E: Accountability&quot;">​</a></h3><p>Holds schools accountable for student outcomes.</p><p><strong>Key takeaways:</strong></p><ul><li>Requires better institutional reporting.</li><li>Links funding to performance metrics.</li></ul><h2 id="title-iv-committee-on-energy-and-commerce" tabindex="-1">Title IV: Committee on Energy and Commerce <a class="header-anchor" href="#title-iv-committee-on-energy-and-commerce" aria-label="Permalink to &quot;Title IV: Committee on Energy and Commerce&quot;">​</a></h2><h3 id="subtitle-a-fossil-fuels-and-infrastructure" tabindex="-1">Subtitle A: Fossil Fuels and Infrastructure <a class="header-anchor" href="#subtitle-a-fossil-fuels-and-infrastructure" aria-label="Permalink to &quot;Subtitle A: Fossil Fuels and Infrastructure&quot;">​</a></h3><p>Shifts energy policy back toward fossil fuel development and deregulation.</p><p><strong>Key takeaways:</strong></p><ul><li>Repeals clean energy incentives from Inflation Reduction Act.</li><li>Promotes oil, gas, and natural gas exports.</li><li>Fast-tracks federal permitting.</li></ul><h3 id="subtitle-b-environment" tabindex="-1">Subtitle B: Environment <a class="header-anchor" href="#subtitle-b-environment" aria-label="Permalink to &quot;Subtitle B: Environment&quot;">​</a></h3><p>Repeals various environmental and emissions control programs.</p><p><strong>Key takeaways:</strong></p><ul><li>Cuts EPA funding for air pollution, greenhouse gas monitoring, and school air quality.</li><li>Halts low-emission initiatives and methane reduction grants.</li></ul><h2 id="title-v-committee-on-financial-services" tabindex="-1">Title V: Committee on Financial Services <a class="header-anchor" href="#title-v-committee-on-financial-services" aria-label="Permalink to &quot;Title V: Committee on Financial Services&quot;">​</a></h2><p>Reins in green finance regulation and ESG disclosures.</p><p><strong>Key takeaways:</strong></p><ul><li>Rescinds climate-focused funds.</li><li>Modifies powers of financial oversight bodies like the CFPB and PCAOB.</li></ul><h2 id="title-vi-committee-on-homeland-security" tabindex="-1">Title VI: Committee on Homeland Security <a class="header-anchor" href="#title-vi-committee-on-homeland-security" aria-label="Permalink to &quot;Title VI: Committee on Homeland Security&quot;">​</a></h2><p>Allocates major funding for border security infrastructure and state-level support.</p><p><strong>Key takeaways:</strong></p><ul><li>Increases border wall funding and technology.</li><li>Expands support for border-state law enforcement.</li><li>Enhances Customs and Border Protection assets.</li></ul><h2 id="title-vii-committee-on-the-judiciary" tabindex="-1">Title VII: Committee on the Judiciary <a class="header-anchor" href="#title-vii-committee-on-the-judiciary" aria-label="Permalink to &quot;Title VII: Committee on the Judiciary&quot;">​</a></h2><h3 id="subtitle-a-immigration-matters" tabindex="-1">Subtitle A: Immigration Matters <a class="header-anchor" href="#subtitle-a-immigration-matters" aria-label="Permalink to &quot;Subtitle A: Immigration Matters&quot;">​</a></h3><h4 id="part-1-immigration-fees" tabindex="-1">Part 1: Immigration Fees <a class="header-anchor" href="#part-1-immigration-fees" aria-label="Permalink to &quot;Part 1: Immigration Fees&quot;">​</a></h4><p>Raises immigration-related fees and enhances enforcement funding.</p><p><strong>Key takeaways:</strong></p><ul><li>New fees for asylum, work permits, and parole applications.</li><li>Increases cost barriers for undocumented immigrants.</li></ul><h4 id="part-2-employment-and-verification" tabindex="-1">Part 2: Employment and Verification <a class="header-anchor" href="#part-2-employment-and-verification" aria-label="Permalink to &quot;Part 2: Employment and Verification&quot;">​</a></h4><p>Implements nationwide E-Verify requirements.</p><p><strong>Key takeaways:</strong></p><ul><li>Mandatory employer verification for all workers.</li><li>Revises rules for worker authorization and fraud prevention.</li></ul><h2 id="title-viii-committee-on-natural-resources" tabindex="-1">Title VIII: Committee on Natural Resources <a class="header-anchor" href="#title-viii-committee-on-natural-resources" aria-label="Permalink to &quot;Title VIII: Committee on Natural Resources&quot;">​</a></h2><h3 id="subtitle-a-resource-development-and-public-lands" tabindex="-1">Subtitle A: Resource Development and Public Lands <a class="header-anchor" href="#subtitle-a-resource-development-and-public-lands" aria-label="Permalink to &quot;Subtitle A: Resource Development and Public Lands&quot;">​</a></h3><p>Promotes energy extraction and limits environmental review on public lands.</p><p><strong>Key takeaways:</strong></p><ul><li>Expands federal oil and gas leasing.</li><li>Streamlines mining and drilling project approvals.</li><li>Reduces climate-based land management requirements.</li></ul><h2 id="title-ix-committee-on-oversight-and-government-reform" tabindex="-1">Title IX: Committee on Oversight and Government Reform <a class="header-anchor" href="#title-ix-committee-on-oversight-and-government-reform" aria-label="Permalink to &quot;Title IX: Committee on Oversight and Government Reform&quot;">​</a></h2><p>Includes program repeals, reviews of federal spending, and symbolic provisions.</p><p><strong>Key takeaways:</strong></p><ul><li>Rescinds unspent COVID-related funds.</li><li>Commemorates past administrations and programs.</li><li>Calls for audits and efficiency reviews.</li></ul><h2 id="title-x-committee-on-transportation-and-infrastructure" tabindex="-1">Title X: Committee on Transportation and Infrastructure <a class="header-anchor" href="#title-x-committee-on-transportation-and-infrastructure" aria-label="Permalink to &quot;Title X: Committee on Transportation and Infrastructure&quot;">​</a></h2><p>Funds energy grid upgrades, ports, highways, and airport modernization.</p><p><strong>Key takeaways:</strong></p><ul><li>Invests in transportation infrastructure resilience.</li><li>Expands FAA and DOT modernization programs.</li><li>Supports rural and coastal transportation needs.</li></ul><h2 id="title-xi-committee-on-ways-and-means-—-the-one-big-beautiful-bill" tabindex="-1">Title XI: Committee on Ways and Means — “The One, Big, Beautiful Bill” <a class="header-anchor" href="#title-xi-committee-on-ways-and-means-—-the-one-big-beautiful-bill" aria-label="Permalink to &quot;Title XI: Committee on Ways and Means — “The One, Big, Beautiful Bill”&quot;">​</a></h2><h3 id="subtitle-a-make-american-families-and-workers-thrive-again" tabindex="-1">Subtitle A: Make American Families and Workers Thrive Again <a class="header-anchor" href="#subtitle-a-make-american-families-and-workers-thrive-again" aria-label="Permalink to &quot;Subtitle A: Make American Families and Workers Thrive Again&quot;">​</a></h3><h4 id="part-1-permanently-preventing-tax-hikes-on-american-families-and-workers" tabindex="-1">Part 1: Permanently Preventing Tax Hikes on American Families and Workers <a class="header-anchor" href="#part-1-permanently-preventing-tax-hikes-on-american-families-and-workers" aria-label="Permalink to &quot;Part 1: Permanently Preventing Tax Hikes on American Families and Workers&quot;">​</a></h4><p>Makes 2017 tax cuts permanent for individuals and families.</p><p><strong>Key takeaways:</strong></p><ul><li>Keeps lower income tax brackets and larger standard deduction.</li><li>Preserves expanded child tax credit and small business pass-through benefits.</li></ul><h4 id="part-2-small-business-and-innovation" tabindex="-1">Part 2: Small Business and Innovation <a class="header-anchor" href="#part-2-small-business-and-innovation" aria-label="Permalink to &quot;Part 2: Small Business and Innovation&quot;">​</a></h4><p>Extends tax breaks for small businesses and innovation.</p><p><strong>Key takeaways:</strong></p><ul><li>Increases Section 179 expensing limits.</li><li>Expands R&amp;D credit and simplifies compliance.</li></ul><h4 id="part-3-investing-in-the-health-of-rural-america-and-main-street" tabindex="-1">Part 3: Investing in the Health of Rural America and Main Street <a class="header-anchor" href="#part-3-investing-in-the-health-of-rural-america-and-main-street" aria-label="Permalink to &quot;Part 3: Investing in the Health of Rural America and Main Street&quot;">​</a></h4><p>Promotes use of HSAs and direct health arrangements.</p><p><strong>Key takeaways:</strong></p><ul><li>Expands HSA eligibility and contribution rules.</li><li>Incentivizes employer-provided care programs.</li></ul><h3 id="subtitle-b-trump-accounts" tabindex="-1">Subtitle B: Trump Accounts <a class="header-anchor" href="#subtitle-b-trump-accounts" aria-label="Permalink to &quot;Subtitle B: Trump Accounts&quot;">​</a></h3><h4 id="part-1-trump-accounts" tabindex="-1">Part 1: Trump Accounts <a class="header-anchor" href="#part-1-trump-accounts" aria-label="Permalink to &quot;Part 1: Trump Accounts&quot;">​</a></h4><p>Creates tax-exempt trust accounts for children with defined contribution and withdrawal rules.</p><p><strong>Key takeaways:</strong></p><ul><li>No income tax on account earnings.</li><li>Subject to capital gains tax upon distribution.</li><li>Must terminate by age 31 or if duplicative.</li></ul><h4 id="part-2-trump-account-pilot-program" tabindex="-1">Part 2: Trump Account Pilot Program <a class="header-anchor" href="#part-2-trump-account-pilot-program" aria-label="Permalink to &quot;Part 2: Trump Account Pilot Program&quot;">​</a></h4><p>Provides $1,000 seed contribution per eligible child.</p><p><strong>Key takeaways:</strong></p><ul><li>Treasury administers accounts.</li><li>Automatically credited upon qualification.</li></ul><h3 id="subtitle-c-make-america-win-again" tabindex="-1">Subtitle C: Make America Win Again <a class="header-anchor" href="#subtitle-c-make-america-win-again" aria-label="Permalink to &quot;Subtitle C: Make America Win Again&quot;">​</a></h3><h4 id="part-1-working-families-over-elites" tabindex="-1">Part 1: Working Families Over Elites <a class="header-anchor" href="#part-1-working-families-over-elites" aria-label="Permalink to &quot;Part 1: Working Families Over Elites&quot;">​</a></h4><p>Ends tax benefits seen as favoring high-income households.</p><p><strong>Key takeaways:</strong></p><ul><li>Eliminates EV and green energy tax credits for wealthy individuals.</li><li>Closes loopholes benefiting upper-income earners.</li></ul><h4 id="part-2-middle-class-opportunity-through-capitalism" tabindex="-1">Part 2: Middle-Class Opportunity Through Capitalism <a class="header-anchor" href="#part-2-middle-class-opportunity-through-capitalism" aria-label="Permalink to &quot;Part 2: Middle-Class Opportunity Through Capitalism&quot;">​</a></h4><p>Expands financial tools for average Americans.</p><p><strong>Key takeaways:</strong></p><ul><li>Broadens retirement and 529 plan access.</li><li>Encourages savings and investment.</li></ul><h3 id="subtitle-d-increase-in-debt-limit" tabindex="-1">Subtitle D: Increase in Debt Limit <a class="header-anchor" href="#subtitle-d-increase-in-debt-limit" aria-label="Permalink to &quot;Subtitle D: Increase in Debt Limit&quot;">​</a></h3><h4 id="part-1-debt-limit-adjustment" tabindex="-1">Part 1: Debt Limit Adjustment <a class="header-anchor" href="#part-1-debt-limit-adjustment" aria-label="Permalink to &quot;Part 1: Debt Limit Adjustment&quot;">​</a></h4><p>Raises national debt ceiling to reflect new legislative priorities.</p><p><strong>Key takeaways:</strong></p><ul><li>Statutory adjustment with no sunset.</li><li>Accommodates expanded tax credits and new account structures.</li></ul><p>Source: <a href="https://www.congress.gov/bill/119th-congress/house-bill/1" target="_blank" rel="noreferrer">https://www.congress.gov/bill/119th-congress/house-bill/1</a></p>',113)]))}const h=t(r,[["render",l]]);export{p as __pageData,h as default};
